/**
 * Renders a form from a provider's JSON Schema (generated by the backend's Pydantic models).
 * This is what makes new integrations usable in the UI without frontend changes.
 */
import { useState } from "react";
import type { JsonSchema } from "../api/types";
import { humanize } from "../lib/format";

type Values = Record<string, unknown>;

interface Resolved {
  schema: JsonSchema;
  nullable: boolean;
}

function resolve(schema: JsonSchema, root: JsonSchema): Resolved {
  let s = schema;
  let nullable = false;
  if (s.$ref) s = deref(s.$ref, root);
  if (s.anyOf) {
    const nonNull = s.anyOf.filter((x) => x.type !== "null");
    nullable = nonNull.length !== s.anyOf.length;
    const inner = nonNull[0] ? (nonNull[0].$ref ? deref(nonNull[0].$ref, root) : nonNull[0]) : {};
    s = { ...inner, title: schema.title ?? inner.title, description: schema.description ?? inner.description, default: schema.default };
  }
  return { schema: s, nullable };
}

function deref(ref: string, root: JsonSchema): JsonSchema {
  const name = ref.split("/").pop() ?? "";
  return root.$defs?.[name] ?? {};
}

function kindOf(s: JsonSchema): string {
  if (s.enum) return "enum";
  const t = Array.isArray(s.type) ? s.type.find((x) => x !== "null") : s.type;
  if (t === "object") return "map";
  if (t === "array") return "list";
  return t ?? "string";
}

export function defaultsFor(schema: JsonSchema): Values {
  const out: Values = {};
  for (const [key, prop] of Object.entries(schema.properties ?? {})) {
    if (prop.default !== undefined && prop.default !== null) out[key] = prop.default;
  }
  return out;
}

/** Convert form values into the payload: drop empty optional fields. */
export function cleanValues(values: Values): Values {
  const out: Values = {};
  for (const [k, v] of Object.entries(values)) {
    if (v === "" || v === undefined || v === null) continue;
    out[k] = v;
  }
  return out;
}

/** Comma-separated list input that keeps the raw text while typing. */
function ListInput({ id, describedBy, initial, onChange }: {
  id: string;
  describedBy?: string;
  initial: string;
  onChange: (parts: string[]) => void;
}) {
  const [text, setText] = useState(initial);
  return (
    <input
      id={id}
      aria-describedby={describedBy}
      value={text}
      placeholder="comma separated"
      onChange={(e) => {
        setText(e.target.value);
        onChange(e.target.value.split(",").map((x) => x.trim()).filter(Boolean));
      }}
    />
  );
}

export function SchemaForm({
  schema,
  values,
  onChange,
  secret,
  setFields = [],
  idPrefix = "f",
}: {
  schema: JsonSchema;
  values: Values;
  onChange: (v: Values) => void;
  secret?: boolean;
  setFields?: string[];
  idPrefix?: string;
}) {
  const required = new Set(schema.required ?? []);
  const set = (key: string, v: unknown) => onChange({ ...values, [key]: v });

  return (
    <div className="form-grid">
      {Object.entries(schema.properties ?? {}).map(([key, raw]) => {
        const { schema: s } = resolve(raw, schema);
        const kind = kindOf(s);
        const label = (s.title ?? humanize(key)) + (required.has(key) ? " *" : "");
        const id = `${idPrefix}-${key}`;
        const value = values[key];
        const hint = s.description;

        if (kind === "boolean") {
          return (
            <label key={key} className="check full" htmlFor={id}>
              <input id={id} aria-describedby={hint ? `${id}-hint` : undefined} type="checkbox" checked={Boolean(value ?? s.default)} onChange={(e) => set(key, e.target.checked)} />
              {label}
              {hint && <span className="muted small">— {hint}</span>}
            </label>
          );
        }
        if (kind === "enum") {
          return (
            <div key={key} className="field">
              <label htmlFor={id}>{label}</label>
              <select id={id} aria-describedby={hint ? `${id}-hint` : undefined} value={String(value ?? s.default ?? "")} onChange={(e) => set(key, e.target.value)}>
                {!required.has(key) && s.default === undefined && <option value="">—</option>}
                {(s.enum ?? []).map((o) => (
                  <option key={String(o)} value={String(o)}>
                    {String(o)}
                  </option>
                ))}
              </select>
              {hint && <span className="hint" id={`${id}-hint`}>{hint}</span>}
            </div>
          );
        }
        if (kind === "list") {
          const numeric = s.items?.type === "integer" || s.items?.type === "number";
          const text = Array.isArray(value) ? value.join(", ") : "";
          return (
            <div key={key} className="field">
              <label htmlFor={id}>{label}</label>
              <ListInput
                id={id}
                describedBy={hint ? `${id}-hint` : undefined}
                initial={text}
                onChange={(parts) => set(key, numeric ? parts.map(Number).filter((n) => !Number.isNaN(n)) : parts)}
              />
              {hint && <span className="hint" id={`${id}-hint`}>{hint}</span>}
            </div>
          );
        }
        if (kind === "map") {
          const obj = (value as Record<string, string>) ?? {};
          const text = Object.entries(obj).map(([k, v]) => `${k}: ${v}`).join("\n");
          return (
            <div key={key} className="field full">
              <label htmlFor={id}>{label}</label>
              <textarea
                id={id} aria-describedby={hint ? `${id}-hint` : undefined}
                defaultValue={text}
                placeholder="Header-Name: value (one per line)"
                onBlur={(e) => {
                  const next: Record<string, string> = {};
                  e.target.value.split("\n").forEach((line) => {
                    const i = line.indexOf(":");
                    if (i > 0) next[line.slice(0, i).trim()] = line.slice(i + 1).trim();
                  });
                  set(key, next);
                }}
              />
              {hint && <span className="hint" id={`${id}-hint`}>{hint}</span>}
            </div>
          );
        }
        const numeric = kind === "integer" || kind === "number";
        const long = key.includes("pem") || key === "body" || key === "query";
        const isSet = setFields.includes(key);
        return (
          <div key={key} className={`field ${long ? "full" : ""}`}>
            <label htmlFor={id}>{label}</label>
            {long ? (
              <textarea id={id} aria-describedby={hint ? `${id}-hint` : undefined} value={String(value ?? "")} onChange={(e) => set(key, e.target.value)} spellCheck={false} className="mono" />
            ) : (
              <input
                id={id} aria-describedby={hint ? `${id}-hint` : undefined}
                type={secret ? "password" : numeric ? "number" : "text"}
                autoComplete={secret ? "new-password" : "off"}
                step={kind === "number" ? "any" : undefined}
                value={value === undefined || value === null ? "" : String(value)}
                placeholder={secret && isSet ? "•••••••• (stored — leave blank to keep)" : s.default !== undefined && s.default !== null ? String(s.default) : ""}
                onChange={(e) => {
                  const v = e.target.value;
                  set(key, numeric ? (v === "" ? "" : Number(v)) : v);
                }}
              />
            )}
            {hint && <span className="hint" id={`${id}-hint`}>{hint}</span>}
          </div>
        );
      })}
    </div>
  );
}
